"use client"

import {
  ColumnFiltersState,
  SortingState,
  VisibilityState,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table"

import * as React from "react"

import { TsTableColumnDef, TsTableRowAction, generateColumns } from "./columns"
import { TsTablePagination } from "./ts-table-pagination"
import { TsTableToolbar } from "./ts-table-toolbar"
import { TsTableView } from "./ts-table-view"

export interface TsTableProps<TData extends Record<string, unknown> = Record<string, unknown>> {
  data: TData[]
  columnDefinitions: TsTableColumnDef[]
  title?: string
  showCreateButton?: boolean
  showImportButton?: boolean
  showExportButton?: boolean
  showColumnSelector?: boolean
  enableSelection?: boolean
  onRowClick?: (row: TData, columnKey?: string) => void
  onCreateClick?: () => void
  onAction?: (action: string, row: TData) => void
  pageSize?: number
  pageSizeOptions?: number[]
  singleItemActions?: string // "action/Label,..."
  predefinedFilters?: Record<string, unknown>
}

export function TsTable<TData extends Record<string, unknown> = Record<string, unknown>>({
  data: initialData,
  columnDefinitions,
  title,
  showCreateButton = true,
  showImportButton = true,
  showExportButton = true,
  showColumnSelector = true,
  enableSelection = true,
  onRowClick,
  onCreateClick,
  onAction,
  pageSize = 10,
  pageSizeOptions = [5, 10, 20, 50, 100],
  singleItemActions,
  predefinedFilters,
}: TsTableProps<TData>) {
  const [data, setData] = React.useState(initialData)
  const [sorting, setSorting] = React.useState<SortingState>([])

  // Initialize filters with predefined filters if available
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>(() => {
    if (!predefinedFilters) return []
    return Object.entries(predefinedFilters).map(([id, value]) => ({ id, value: String(value) }))
  })

  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>(
    columnDefinitions.reduce((acc, col) => {
      if (col.visible === false) acc[col.key] = false
      return acc
    }, {} as VisibilityState)
  )
  const [rowSelection, setRowSelection] = React.useState({})
  const [globalFilter, setGlobalFilter] = React.useState("")

  // Update data if initialData changes
  React.useEffect(() => {
    setData(initialData)
  }, [initialData])

  // Parse row actions
  const rowActions = React.useMemo<TsTableRowAction[]>(() => {
    if (!singleItemActions) return []
    return singleItemActions.split(",").map((s) => {
      const parts = s.split("/")
      return { action: parts[0].trim(), label: parts[1]?.trim() || parts[0].trim() }
    })
  }, [singleItemActions])

  // Generate columns definition
  const columns = React.useMemo(
    () =>
      generateColumns<TData>(columnDefinitions, enableSelection, onRowClick, rowActions, onAction),
    [columnDefinitions, enableSelection, onRowClick, rowActions, onAction]
  )

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
      globalFilter,
    },
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    initialState: {
      pagination: {
        pageSize: pageSize,
      },
    },
  })

  const handleImport = (newData: TData[]) => {
    setData((prev) => [...prev, ...newData])
  }

  return (
    <div className="w-full space-y-4">
      <TsTableToolbar
        table={table}
        title={title}
        showCreateButton={showCreateButton}
        showImportButton={showImportButton}
        showExportButton={showExportButton}
        showColumnSelector={showColumnSelector}
        onCreateClick={onCreateClick}
        onImportClick={handleImport}
      />
      <TsTableView table={table} onRowClick={onRowClick ? (row) => onRowClick(row) : undefined} />
      <TsTablePagination table={table} pageSizeOptions={pageSizeOptions} />
    </div>
  )
}

"use client"

import { ColumnDef } from "@tanstack/react-table"
import { ArrowDown, ArrowUp, ArrowUpDown, MoreVertical } from "lucide-react"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

import { cn } from "@/lib/utils"

import { booleanFilter, dateFilter, numberFilter } from "./filters"

export interface TsTableColumnDef {
  key: string
  title: string
  type?: "text" | "number" | "date" | "boolean"
  sortable?: boolean
  filterable?: boolean
  visible?: boolean
  width?: number | string
  align?: "left" | "center" | "right"
  canBeCopied?: boolean
  isClickable?: boolean
}

export interface TsTableRowAction {
  action: string
  label: string
}

export function generateColumns<TData>(
  columnDefinitions: TsTableColumnDef[],
  enableSelection: boolean,
  onRowClick?: (row: TData, columnKey?: string) => void,
  rowActions?: TsTableRowAction[],
  onAction?: (action: string, row: TData) => void
): ColumnDef<TData>[] {
  const cols: ColumnDef<TData>[] = []

  // 1. Selection column
  if (enableSelection) {
    cols.push({
      id: "select",
      header: ({ table }) => (
        <Checkbox
          checked={
            table.getIsAllPageRowsSelected() ||
            (table.getIsSomePageRowsSelected() && "indeterminate")
          }
          onCheckedChange={(value: boolean) => table.toggleAllPageRowsSelected(!!value)}
          aria-label="Select all"
          className="translate-y-[2px]"
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(value: boolean) => row.toggleSelected(!!value)}
          aria-label="Select row"
          onClick={(e: React.MouseEvent) => e.stopPropagation()}
          className="translate-y-[2px]"
        />
      ),
      enableSorting: false,
      enableHiding: false,
      size: 40,
    })
  }

  // 2. Row Actions Column (if enabled)
  if (rowActions && rowActions.length > 0) {
    cols.push({
      id: "actions",
      enableHiding: false,
      size: 40,
      cell: ({ row }) => {
        return (
          <div className="flex justify-center" onClick={(e) => e.stopPropagation()}>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" className="h-8 w-8 p-0">
                  <span className="sr-only">Open menu</span>
                  <MoreVertical className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuLabel>Actions</DropdownMenuLabel>
                {rowActions.map((action, idx) => (
                  <DropdownMenuItem
                    key={idx}
                    onClick={() => onAction?.(action.action, row.original)}
                  >
                    {action.label}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        )
      },
    })
  }

  // 3. Data columns
  columnDefinitions.forEach((def) => {
    cols.push({
      accessorKey: def.key,
      header: ({ column }) => {
        return (
          <div
            className={cn(
              "flex items-center space-x-2",
              def.align === "center" && "justify-center",
              def.align === "right" && "justify-end"
            )}
          >
            <Button
              variant="ghost"
              size="sm"
              className="-ml-3 h-8 data-[state=open]:bg-accent"
              onClick={() =>
                def.sortable !== false && column.toggleSorting(column.getIsSorted() === "asc")
              }
              disabled={def.sortable === false}
            >
              <span>{def.title}</span>
              {def.sortable !== false &&
                (column.getIsSorted() === "desc" ? (
                  <ArrowDown className="ml-2 h-4 w-4" />
                ) : column.getIsSorted() === "asc" ? (
                  <ArrowUp className="ml-2 h-4 w-4" />
                ) : (
                  <ArrowUpDown className="ml-2 h-4 w-4 opacity-50" />
                ))}
            </Button>
          </div>
        )
      },
      cell: ({ row }) => {
        const value = row.getValue(def.key)

        let formattedValue: React.ReactNode = String(value ?? "")

        if (def.type === "number" && typeof value === "number") {
          formattedValue = value.toLocaleString("en-US", {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
          })
        } else if (def.type === "date" && value) {
          formattedValue = new Date(value as string).toLocaleDateString("en-US")
        } else if (def.type === "boolean") {
          formattedValue = (
            <div
              className={cn(
                "flex",
                def.align === "center" && "justify-center",
                def.align === "right" && "justify-end"
              )}
            >
              <Checkbox checked={!!value} disabled className="opacity-70 cursor-default" />
            </div>
          )
        }

        return (
          <div
            className={cn(
              "truncate",
              def.align === "center" && "text-center",
              def.align === "right" && "text-right",
              def.isClickable && "text-primary hover:underline cursor-pointer font-medium"
            )}
            onClick={() => def.isClickable && onRowClick?.(row.original, def.key)}
          >
            {formattedValue}
          </div>
        )
      },
      enableSorting: def.sortable ?? true,
      enableColumnFilter: def.filterable ?? true,
      size: typeof def.width === "number" ? def.width : 200,
      filterFn: (row, id, value, addMeta) => {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        if (def.type === "number") return numberFilter(row as any, id, value, addMeta)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        if (def.type === "date") return dateFilter(row as any, id, value, addMeta)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        if (def.type === "boolean") return booleanFilter(row as any, id, value, addMeta)
        return true // default text filter handled by table
      },
      meta: {
        type: def.type,
      },
    })
  })

  return cols
}

import { FilterFn } from "@tanstack/react-table"

// Helper for parsing number range/operator
function parseNumberRange(filterValue: string) {
  const value = filterValue.trim()

  // Range 10..20
  if (value.includes("..")) {
    const parts = value.split("..")
    return {
      min: parts[0] ? parseFloat(parts[0]) : null,
      max: parts[1] ? parseFloat(parts[1]) : null,
    }
  }
  // Greater/less than
  if (value.startsWith(">=")) return { min: parseFloat(value.substring(2)), max: null }
  if (value.startsWith("<=")) return { min: null, max: parseFloat(value.substring(2)) }
  if (value.startsWith(">")) return { min: parseFloat(value.substring(1)) + 0.000001, max: null } // hack for strict
  if (value.startsWith("<")) return { min: null, max: parseFloat(value.substring(1)) - 0.000001 }

  // Equality (or partial match for text, but we are in numbers here)
  // If it's a valid number, do we treat it as exact match or startsWith?
  // Original code does fallback to text match if it's not a range.
  const floatVal = parseFloat(value)
  if (!isNaN(floatVal)) return { exact: floatVal }

  return null
}

export const numberFilter: FilterFn<unknown> = (row, columnId, filterValue) => {
  const cellValue = row.getValue(columnId) as number
  if (typeof cellValue !== "number") return false

  const range = parseNumberRange(String(filterValue))
  if (!range) {
    // Fallback to string match (original behavior)
    return String(cellValue).includes(String(filterValue))
  }

  if (range.exact !== undefined) {
    // Original code for exact match also does text match fallback,
    // but if we want precise numbers:
    return cellValue === range.exact || String(cellValue).startsWith(String(filterValue))
  }

  if (range.min !== null && cellValue < range.min) return false
  if (range.max !== null && cellValue > range.max) return false

  return true
}

// Helper for parsing data
// Original code normalizes to "local midnight"
function parseDate(input: string): Date | null {
  const d = new Date(input)
  if (isNaN(d.getTime())) return null
  return new Date(d.getFullYear(), d.getMonth(), d.getDate())
}

export const dateFilter: FilterFn<unknown> = (row, columnId, filterValue) => {
  const cellValue = row.getValue(columnId)
  if (!cellValue) return false

  const cellDate = new Date(cellValue as string)
  if (isNaN(cellDate.getTime())) return false
  const normalizedCellDate = new Date(
    cellDate.getFullYear(),
    cellDate.getMonth(),
    cellDate.getDate()
  )

  // Try parsing filterValue as range
  const val = String(filterValue).trim()

  if (val.includes("..")) {
    const [start, end] = val.split("..")
    const min = start ? parseDate(start) : null
    const max = end ? parseDate(end) : null

    if (min && normalizedCellDate < min) return false
    if (max && normalizedCellDate > max) return false
    return true
  }

  if (val.startsWith(">=")) {
    const min = parseDate(val.substring(2))
    return min ? normalizedCellDate >= min : true
  }
  if (val.startsWith("<=")) {
    const max = parseDate(val.substring(2))
    return max ? normalizedCellDate <= max : true
  }
  if (val.startsWith(">")) {
    const min = parseDate(val.substring(1))
    return min ? normalizedCellDate > min : true
  }
  if (val.startsWith("<")) {
    const max = parseDate(val.substring(1))
    return max ? normalizedCellDate < max : true
  }

  // Equality date
  const exactDate = parseDate(val)
  if (exactDate) {
    return normalizedCellDate.getTime() === exactDate.getTime()
  }

  // Fallback: Text search in formatted date (en-US)
  const formatted = new Intl.DateTimeFormat("en-US").format(normalizedCellDate)
  return formatted.includes(val)
}

export const booleanFilter: FilterFn<unknown> = (row, columnId, filterValue) => {
  const cellValue = row.getValue(columnId)
  const val = String(filterValue)

  if (val === "true") return cellValue === true
  if (val === "false") return cellValue === false
  return true // 'all' or empty
}

"use client"

import { Table } from "@tanstack/react-table"
import { Download, Plus, Search, Settings2, Upload } from "lucide-react"
import * as XLSX from "xlsx"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"

interface TsTableToolbarProps<TData> {
  table: Table<TData>
  showCreateButton?: boolean
  showImportButton?: boolean
  showExportButton?: boolean
  showColumnSelector?: boolean
  onCreateClick?: () => void
  onImportClick?: (data: TData[]) => void
  title?: string
}

export function TsTableToolbar<TData>({
  table,
  showCreateButton = true,
  showImportButton = true,
  showExportButton = true,
  showColumnSelector = true,
  onCreateClick,
  onImportClick,
  title,
}: TsTableToolbarProps<TData>) {
  const handleExport = () => {
    const data = table.getFilteredRowModel().rows.map((row) => row.original)
    const ws = XLSX.utils.json_to_sheet(data)
    const wb = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(wb, ws, "Data")
    XLSX.writeFile(wb, `export-${new Date().toISOString().split("T")[0]}.xlsx`)
  }

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (event) => {
      const bstr = event.target?.result
      if (typeof bstr !== "string") return
      const wb = XLSX.read(bstr, { type: "binary" })
      const wsname = wb.SheetNames[0]
      const ws = wb.Sheets[wsname]
      const data = XLSX.utils.sheet_to_json(ws) as TData[]
      onImportClick?.(data)
    }
    reader.readAsBinaryString(file)
  }

  return (
    <div className="flex items-center justify-between py-4 gap-2">
      <div className="flex flex-1 items-center gap-2">
        <div className="relative w-64">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search..."
            value={(table.getState().globalFilter as string) ?? ""}
            onChange={(event) => table.setGlobalFilter(event.target.value)}
            className="pl-8 h-9"
          />
        </div>
        {title && <h2 className="text-lg font-semibold ml-4">{title}</h2>}
      </div>

      <div className="flex items-center gap-2">
        {showColumnSelector && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm" className="h-9 ml-auto flex gap-2">
                <Settings2 className="h-4 w-4" />
                Columns
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-[200px]">
              <DropdownMenuLabel>View columns</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {table
                .getAllColumns()
                .filter((column) => column.getCanHide())
                .map((column) => {
                  return (
                    <DropdownMenuCheckboxItem
                      key={column.id}
                      className="capitalize"
                      checked={column.getIsVisible()}
                      onCheckedChange={(value) => column.toggleVisibility(!!value)}
                    >
                      {typeof column.columnDef.header === "string"
                        ? column.columnDef.header
                        : column.id}
                    </DropdownMenuCheckboxItem>
                  )
                })}
            </DropdownMenuContent>
          </DropdownMenu>
        )}

        {showExportButton && (
          <Button variant="outline" size="sm" className="h-9 gap-2" onClick={handleExport}>
            <Download className="h-4 w-4" />
            Export
          </Button>
        )}

        {showImportButton && (
          <div className="relative">
            <Button variant="outline" size="sm" className="h-9 gap-2" asChild>
              <label className="cursor-pointer">
                <Upload className="h-4 w-4" />
                Import
                <input
                  type="file"
                  className="hidden"
                  accept=".xlsx,.xls,.csv,.json"
                  onChange={handleImport}
                />
              </label>
            </Button>
          </div>
        )}

        {showCreateButton && (
          <Button size="sm" className="h-9 gap-2" onClick={onCreateClick}>
            <Plus className="h-4 w-4" />
            New record
          </Button>
        )}
      </div>
    </div>
  )
}

"use client"

import { Table as TanStackTable, flexRender } from "@tanstack/react-table"

import * as React from "react"

import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

import { cn } from "@/lib/utils"

interface TsTableViewProps<TData> {
  table: TanStackTable<TData>
  onRowClick?: (row: TData) => void
}

export function TsTableView<TData>({ table, onRowClick }: TsTableViewProps<TData>) {
  return (
    <div className="rounded-md border bg-card overflow-hidden">
      <Table>
        <TableHeader className="bg-muted/50">
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => {
                const meta = header.column.columnDef.meta as { type?: string } | undefined
                return (
                  <TableHead
                    key={header.id}
                    className="align-top py-2 px-4 font-bold text-muted-foreground"
                    style={{ width: header.getSize() }}
                  >
                    <div className="flex flex-col gap-2">
                      {/* Header Title & Sort Button */}
                      <div className="h-8 flex items-center">
                        {header.isPlaceholder
                          ? null
                          : flexRender(header.column.columnDef.header, header.getContext())}
                      </div>

                      {/* Filter Input */}
                      {header.column.getCanFilter() ? (
                        <div className="pb-2">
                          {meta?.type === "boolean" ? (
                            <Select
                              value={(header.column.getFilterValue() ?? "all") as string}
                              onValueChange={(val: string) =>
                                header.column.setFilterValue(val === "all" ? "" : val)
                              }
                            >
                              <SelectTrigger className="h-8 text-xs bg-background w-full">
                                <SelectValue placeholder="All" />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="all">All</SelectItem>
                                <SelectItem value="true">Yes</SelectItem>
                                <SelectItem value="false">No</SelectItem>
                              </SelectContent>
                            </Select>
                          ) : (
                            <Input
                              placeholder={
                                meta?.type === "number"
                                  ? ">10, 10..20"
                                  : meta?.type === "date"
                                    ? ">2023-01-01"
                                    : "Filter..."
                              }
                              value={(header.column.getFilterValue() ?? "") as string}
                              onChange={(event) => header.column.setFilterValue(event.target.value)}
                              onKeyDown={(e) => {
                                if (e.key === "Escape") {
                                  e.preventDefault()
                                  header.column.setFilterValue("")
                                }
                              }}
                              className="h-8 text-xs bg-background"
                            />
                          )}
                        </div>
                      ) : (
                        <div className="h-0 pb-2" />
                      )}
                    </div>
                  </TableHead>
                )
              })}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {table.getRowModel().rows?.length ? (
            table.getRowModel().rows.map((row) => (
              <TableRow
                key={row.id}
                data-state={row.getIsSelected() && "selected"}
                className={cn(
                  "hover:bg-muted/50 transition-colors cursor-default",
                  onRowClick && "cursor-pointer"
                )}
                onClick={() => onRowClick?.(row.original)}
              >
                {row.getVisibleCells().map((cell) => (
                  <TableCell key={cell.id} className="p-3">
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))
          ) : (
            <TableRow>
              <TableCell colSpan={table.getAllColumns().length} className="h-24 text-center">
                No records found.
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
}
